using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class RetainerStartTests
{
    static WorldSession New()=>new(RetainerStart.Create());
    static EntityId Task(WorldSession s)=>s.DiagnosticSnapshot().Tasks.Single(t=>t.Action==ActionKind.Inspect).Id;
    static void Open(WorldSession s){var c=RegionalWork.Inbox(s).Single();Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,c.Message,s.Revision).Code);}
    static void Advance(WorldSession s,long at){s.SetPaused(false);s.AdvanceTo(at);}
    static void Finish(WorldSession s){if(s.Seconds<2)Advance(s,2);if(RegionalWork.Inbox(s).Any(c=>c.CanOpen))Open(s);if(s.Seconds<9)Advance(s,9);}
    static WorldSession Restore(WorldSession s){s.SetPaused(true);var root=Path.Combine(Path.GetTempPath(),"hakutai-retainer-"+Guid.NewGuid().ToString("N"));var store=new GenerationSaveStore(root,RetainerStart.Create().Definitions);store.Save(s,"case",s.DiagnosticSnapshot().WorldId,new(0,1));var host=new WorldSessionHost(New());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("case"),host.Current,host.Current.Revision));return host.Current;}
    [Fact] public void MembershipServiceAndInitialKnowledgeAreSeparate(){var w=RetainerStart.Create();Assert.Equal(RetainerStart.House,w.Memberships.Single(m=>m.Subject==w.PlayerControl).Target);Assert.Equal(RetainerStart.Lord,w.ServiceBonds.Single(b=>b.Subject==w.PlayerControl).Target);Assert.Single(w.Knowledge,k=>k.Character==w.PlayerControl);Assert.Single(w.Knowledge,k=>k.Character==RetainerStart.Lord);Assert.True(StartConfiguration.Check(w,StartConfiguration.Describe(w,w.PlayerControl,StartTemplate.Retainer,PersonOrigin.Created,PersonalStart.Policy),PersonalStart.Policy).Eligible);}
    [Fact] public void RankDoesNotGrantArmyLandOrTax(){var w=RetainerStart.Create();Assert.DoesNotContain(w.Units,u=>u.Commander==w.PlayerControl);Assert.DoesNotContain(w.LandRights,l=>l.Subject==w.PlayerControl);Assert.DoesNotContain(w.Grants,g=>g.Agent==w.PlayerControl&&g.Actions.Contains(ActionKind.Transfer));Assert.Equal(ResultCode.NotAvailable,new WorldSession(w).SetRegionalActive(true,0).Code);}
    [Fact] public void OnlyDirectLordOffersABindingOrder(){var s=New();s.AdvanceTo(1);var t=s.DiagnosticSnapshot().Tasks.Single();Assert.Equal(TaskKind.BindingOrder,t.Kind);Assert.Equal(RetainerStart.Lord,t.Issuer);Assert.Equal(PersonalStart.Person,t.Executor);Assert.Empty(RegionalWork.Inbox(s));}
    [Fact] public void OtherHouseStillOffersVoluntaryWork(){var s=New();Assert.Equal(ResultCode.Accepted,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:retainer-travel","kofu"),s.Revision).Code);s.AdvanceTo(1);long at=s.DiagnosticSnapshot().Branches!.Journeys.Single().Legs[^1].EndAt;Advance(s,at+1);var t=s.DiagnosticSnapshot().Tasks.Last();Assert.Equal(new EntityId("person:shingen"),t.Issuer);Assert.Equal(TaskKind.VoluntaryRequest,t.Kind);}
    [Fact] public void OpenedOrderUsesExistingExecutionWithoutAssent(){var s=New();s.AdvanceTo(2);Open(s);Assert.False(RegionalWork.Inbox(s).Single().CanDecide);Assert.Equal(AgreementPhase.Active,s.DiagnosticSnapshot().Tasks.Single().Agreement);Finish(s);Assert.Equal(ExecutionPhase.Completed,s.DiagnosticSnapshot().Tasks.Single().Execution);}
    [Fact] public void InterruptionAndExplanationAreIndependentPhysicalMessages(){var s=New();s.AdvanceTo(2);Open(s);Assert.Equal(ResultCode.Accepted,s.InterruptMission(Task(s),s.PlayerControl,s.Revision).Code);Assert.Equal(ResultCode.Accepted,s.ExplainMission(Task(s),s.PlayerControl,MissionReview.Explanation.OwnDecision,s.Revision).Code);Assert.Equal("本人の理由書状は未認識",MissionReview.View(s,RetainerStart.Lord).Single().Reason);Advance(s,6);var view=MissionReview.View(s,RetainerStart.Lord).Single();Assert.Contains("自己判断",view.Reason);Assert.Contains("中断",view.Difference);Assert.Equal("責任・処分は未審査",view.Liability);}
    [Fact] public void UnknownOrSealedOrderCannotBeInterrupted(){var s=New();s.AdvanceTo(1);Assert.False(MissionReview.CanInterrupt(s,Task(s),s.PlayerControl));Assert.Equal(ResultCode.NotAvailable,s.InterruptMission(Task(s),s.PlayerControl,s.Revision).Code);Advance(s,2);Assert.False(MissionReview.CanInterrupt(s,Task(s),s.PlayerControl));Open(s);Assert.True(MissionReview.CanInterrupt(s,Task(s),s.PlayerControl));}
    [Fact] public void ReasonContentsAreNotKnownBeforePhysicalDelivery(){var s=New();s.AdvanceTo(2);Open(s);s.InterruptMission(Task(s),s.PlayerControl,s.Revision);s.ExplainMission(Task(s),s.PlayerControl,MissionReview.Explanation.ClaimedDanger,s.Revision);var before=MissionReview.View(s,RetainerStart.Lord).Single();Assert.Equal("本人の理由書状は未認識",before.Reason);Assert.Empty(before.Evidence);Advance(s,3);Assert.Contains("危険回避",MissionReview.View(s,RetainerStart.Lord).Single().Reason);}
    [Fact] public void AnotherLordOrUnknownAgreementIsRejected(){var w=RetainerStart.Create();w.ServiceBonds=w.ServiceBonds.Select(b=>b.Subject==w.PlayerControl?b with{Target=new("person:shingen")}:b).ToArray();Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));w=RetainerStart.Create();w.Knowledge=w.Knowledge.Where(k=>k.Character!=w.PlayerControl).ToArray();Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));}
    [Fact] public void OldRoninAndNpcStatesRetainExactDefinitions(){var ronin=ContractJson.Write(PersonalStart.Create());var npc=ContractJson.Write(NpcWork.Create());RetainerStart.Create();Assert.Equal(ronin,ContractJson.Write(PersonalStart.Create()));Assert.Equal(npc,ContractJson.Write(NpcWork.Create()));Assert.NotEqual(PersonalStart.Create().Definitions.Version,RetainerStart.Create().Definitions.Version);}
    [Theory][InlineData(1)][InlineData(2)][InlineData(4)][InlineData(6)][InlineData(9)]
    public void RestoredOrderContinuesWithExactWorld(long at){var s=New();s.AdvanceTo(Math.Min(2,at));if(at>2){Open(s);Advance(s,at);}var restored=Restore(s);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(restored.DiagnosticSnapshot()));Finish(s);Finish(restored);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(restored.DiagnosticSnapshot()));}
    [Theory][InlineData(2)][InlineData(3)][InlineData(4)][InlineData(5)][InlineData(6)]
    public void InterruptedSavePreservesReportsAndReasons(long at){var s=New();s.AdvanceTo(2);Open(s);s.InterruptMission(Task(s),s.PlayerControl,s.Revision);s.ExplainMission(Task(s),s.PlayerControl,MissionReview.Explanation.ClaimedDanger,s.Revision);Advance(s,at);var restored=Restore(s);Advance(s,9);Advance(restored,9);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(restored.DiagnosticSnapshot()));Assert.Equal(ExecutionPhase.Stopped,s.DiagnosticSnapshot().Tasks.Single().Execution);}
    [Theory][InlineData("future")][InlineData("expiry")][InlineData("role")][InlineData("army")][InlineData("tax")]
    public void NoUnregisteredStartingRightsOrPeriods(string change){var w=RetainerStart.Create();switch(change){case "future":w.ServiceBonds=w.ServiceBonds.Select(b=>b.Subject==w.PlayerControl?b with{From=1}:b).ToArray();break;case "expiry":w.ServiceBonds=w.ServiceBonds.Select(b=>b.Subject==w.PlayerControl?b with{Until=1}:b).ToArray();break;case "role":w.Offices=[..w.Offices,new(new("office:invented"),w.PlayerControl,ContractFixture.Castle,"castellan",RetainerStart.Basis,0,long.MaxValue,0)];break;case "army":w.Definitions=w.Definitions with{Armies=[..w.Definitions.Armies,new(new("army:invented"),RetainerStart.House,w.PlayerControl)]};w.Units=[..w.Units,new(new("unit:invented"),new("army:invented"),w.PlayerControl,RetainerStart.House,100,0)];break;case "tax":w.Grants=[..w.Grants,w.Grants.First(g=>g.Actions.Contains(ActionKind.Transfer)) with{Id=new("grant:invented"),Agent=w.PlayerControl}];break;}Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));}
}
